import itertools
L=np.log(eps)
Ef={'1':np.ones_like(eps),'e':eps,'e2':eps**2,'1/e':1/eps,'L':L,'L2':L**2,'1/e2':1/eps**2,'eL':eps*L,'expe':np.exp(-eps),'se':np.sqrt(eps),'e3':eps**3,'L/e':L/eps,'e^-.5':eps**-0.5,'e^1.5':eps**1.5}
